package com.shanghai.translator;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.speech.tts.TextToSpeech;import android.view.*;import android.widget.*;import com.google.mlkit.nl.translate.*;import com.google.mlkit.common.model.DownloadConditions;import java.util.*;import java.io.*;

public class MainActivity extends Activity {
 String[] names={"Русский","English","中文"};String[] codes={TranslateLanguage.RUSSIAN,TranslateLanguage.ENGLISH,TranslateLanguage.CHINESE};String[] locales={"ru","en","zh"};Spinner from,to;EditText input;TextView output,status;LinearLayout root;Translator translator;TextToSpeech tts;boolean voiceReady=false;String currentResult="";
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density);} TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(30,45,65));t.setPadding(dp(6),dp(9),dp(6),dp(9));return t;}
 Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}
 void add(View v){root.addView(v);} void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(14,61,95));tts=new TextToSpeech(this, code->{voiceReady=code==TextToSpeech.SUCCESS;});home();}
 void base(String title){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(12),dp(16),dp(28));root.setBackgroundColor(Color.rgb(247,250,252));scroll.addView(root);setContentView(scroll);add(text(title,25));}
 void home(){base("Shanghai Translator 🇷🇺 🇬🇧 🇨🇳");add(text("Свободный перевод офлайн после загрузки языковых моделей. Разговорник работает сразу.",14));
 from=new Spinner(this);to=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names);from.setAdapter(a);to.setAdapter(a);to.setSelection(2);LinearLayout langs=new LinearLayout(this);langs.setOrientation(LinearLayout.HORIZONTAL);langs.addView(from,new LinearLayout.LayoutParams(0,dp(55),1));Button swap=button("⇄");langs.addView(swap);langs.addView(to,new LinearLayout.LayoutParams(0,dp(55),1));add(langs);swap.setOnClickListener(v->{int x=from.getSelectedItemPosition();from.setSelection(to.getSelectedItemPosition());to.setSelection(x);});
 input=new EditText(this);input.setHint("Введите текст для перевода...");input.setMinLines(4);input.setGravity(Gravity.TOP);add(input);
 Button translate=button("Перевести");add(translate);Button download=button("Загрузить языковую модель");add(download);status=text("Модель загрузится через интернет один раз для выбранного направления.",13);add(status);
 output=text("Перевод появится здесь",23);output.setTextIsSelectable(true);add(output);
 Button speak=button("🔊 Произнести перевод");add(speak);speak.setOnClickListener(v->{if(!voiceReady){toast("Офлайн-голос не установлен");return;}tts.setLanguage(new Locale(locales[to.getSelectedItemPosition()]));tts.speak(currentResult,TextToSpeech.QUEUE_FLUSH,null,"translation");});
 Button copy=button("Копировать перевод");add(copy);copy.setOnClickListener(v->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("translation",currentResult));toast("Скопировано");});
 translate.setOnClickListener(v->perform(false));download.setOnClickListener(v->perform(true));Button phrases=button("📖 Разговорник Шанхая (офлайн)");add(phrases);phrases.setOnClickListener(v->phrasebook());add(text("Важно: языковые модели загружаются по отдельности для каждой пары и направления. После загрузки перевод работает без интернета. Для китайской речи может потребоваться офлайн-пакет TTS в настройках Android.",13));}
 void perform(boolean forceDownload){int i=from.getSelectedItemPosition(),j=to.getSelectedItemPosition();if(i==j){currentResult=input.getText().toString();output.setText(currentResult);return;}if(translator!=null)translator.close();translator=Translation.getClient(new TranslatorOptions.Builder().setSourceLanguage(codes[i]).setTargetLanguage(codes[j]).build());String s=input.getText().toString().trim();if(!forceDownload&&s.isEmpty()){toast("Введите текст");return;}status.setText("Проверка языковой модели...");DownloadConditions conditions=new DownloadConditions.Builder().build();translator.downloadModelIfNeeded(conditions).addOnSuccessListener(unused->{status.setText("Модель готова. Перевод доступен офлайн.");if(!forceDownload)translator.translate(s).addOnSuccessListener(result->{currentResult=result;output.setText(result);}).addOnFailureListener(e->status.setText("Ошибка перевода: "+e.getMessage()));}).addOnFailureListener(e->status.setText("Не удалось загрузить модель. Проверь интернет: "+e.getMessage()));}
 void phrasebook(){base("Разговорник • Shanghai");Button back=button("← Переводчик");add(back);back.setOnClickListener(v->home());EditText search=new EditText(this);search.setHint("Поиск по русскому / English / 中文");add(search);LinearLayout entries=new LinearLayout(this);entries.setOrientation(1);add(entries);ArrayList<String[]> rows=new ArrayList<>();try{BufferedReader br=new BufferedReader(new InputStreamReader(getAssets().open("phrases.tsv"),"UTF-8"));String line;boolean first=true;while((line=br.readLine())!=null){if(first){first=false;continue;}String[] parts=line.split("\t",-1);if(parts.length==5)rows.add(parts);}br.close();}catch(Exception e){toast(e.toString());}Runnable render=()->{entries.removeAllViews();String q=search.getText().toString().toLowerCase(Locale.ROOT);for(String[] p:rows){StringBuilder sb=new StringBuilder();for(String part:p)sb.append(part).append(' ');String all=sb.toString().toLowerCase(Locale.ROOT);if(!all.contains(q))continue;TextView heading=text(p[0]+"  •  "+p[1],16);entries.addView(heading);TextView chinese=text(p[3],23);entries.addView(chinese);entries.addView(text(p[2]+"\n"+p[4],14));LinearLayout actions=new LinearLayout(this);Button show=button("Показать");Button speak=button("🔊");actions.addView(show,new LinearLayout.LayoutParams(0,dp(50),1));actions.addView(speak);entries.addView(actions);show.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(p[1]).setMessage(p[3]+"\n\n"+p[4]).setPositiveButton("Закрыть",null).setNeutralButton("Копировать",(d,w)->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Chinese",p[3]));}).show());speak.setOnClickListener(v->{if(voiceReady){tts.setLanguage(Locale.SIMPLIFIED_CHINESE);tts.speak(p[3],TextToSpeech.QUEUE_FLUSH,null,"phrase");}else toast("Установи офлайн-голос китайского в настройках телефона");});View divider=new View(this);divider.setBackgroundColor(Color.LTGRAY);entries.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));}};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){render.run();}public void afterTextChanged(android.text.Editable e){}});render.run();}
 @Override protected void onDestroy(){if(translator!=null)translator.close();if(tts!=null)tts.shutdown();super.onDestroy();}
}
